// Exact glyph bytes verified against the binary's table at vaddr 0x404047.
// idx3 is U+28BF (E2 A2 BF), *not* U+283F.
const FRAMES: [&str; 8] = [
    "\u{28FE}", "\u{28FD}", "\u{28FB}", "\u{28BF}",
    "\u{287F}", "\u{28DF}", "\u{28EF}", "\u{28F7}",
];

pub struct CyclicProgress {
    count: i32, // C++ offset +0x00, initialized to 0
    total: i32, // C++ offset +0x04, ctor argument
    // frames_ (std::vector<std::string> at +0x08) is an implementation
    // detail; a &'static [&str; 8] is behaviorally equivalent.
}

impl CyclicProgress {
    /// C++: CyclicProgress(int total) : count_(0), total_(total), frames_{...}
    pub fn new(total: i32) -> Self {
        Self { count: 0, total }
    }

    /// C++: void next() { count_ = (count_ + 1) % total_; }
    /// Signed, truncating modulo. Panics when total == 0, mirroring the
    /// C++ `idiv` SIGFPE. wrapping_add mirrors the practical result of the
    /// (technically UB) int overflow at count == i32::MAX.
    pub fn next(&mut self) {
        self.count = self.count.wrapping_add(1) % self.total;
    }

    /// C++: frames_[count_ % frames_.size()]
    /// int -> size_t conversion, hence sign-extend then unsigned modulo.
    fn frame(&self) -> &'static str {
        FRAMES[((self.count as i64 as u64) % FRAMES.len() as u64) as usize]
    }

    /// C++: static_cast<float>(count_) / total_ * 100.0f
    /// MUST be f32 throughout (divss/mulss); f64 gives different output.
    fn percent_f32(&self) -> f32 {
        self.count as f32 / self.total as f32 * 100.0f32
    }

    /// C++: oss << frames_[i] << " " << std::fixed << std::setprecision(1)
    ///          << percent << "%";  ==  printf("%s %.1f%%", glyph, pct)
    pub fn str(&self) -> String {
        // cvtss2sd: widen the f32 result to f64 before formatting.
        let p = self.percent_f32() as f64;
        if p.is_nan() {
            // Rust's {:.1} prints "NaN"; glibc/libstdc++ print "-nan"
            // (x86 default QNaN from 0.0/0.0 is 0xFFC00000, sign bit set).
            format!("{} -nan%", self.frame())
        } else {
            // inf / -inf already match glibc exactly.
            format!("{} {:.1}%", self.frame(), p)
        }
    }
}

impl std::fmt::Display for CyclicProgress {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.str())
    }
}
